from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5

# name -> (lower bound, upper bound or None, error message); collates the
# repeated "is it an int in range" checks for the three grid dimensions.
_GRID_BOUNDS = {
    "width": (1, MAX_DIM, "bad width"),
    "height": (1, MAX_DIM, "bad height"),
    "cell_size": (1, None, "bad cell size"),
}
# every observation must carry all of these integer fields, so a single loop
# stands in for what were four identical branch blocks.
_OBS_FIELDS = ("x", "y", "value", "quality")


def accumulate_grid(raw: object) -> dict:
    if not isinstance(raw, dict):
        return {"ok": False, "error": "malformed input"}
    if not {"grid", "observations", "fill_value"} <= raw.keys():
        return {"ok": False, "error": "missing field"}
    grid = raw["grid"]
    if not isinstance(grid, dict):
        return {"ok": False, "error": "bad grid"}
    if not {"width", "height", "cell_size"} <= grid.keys():
        return {"ok": False, "error": "bad grid"}

    dims = {}
    for name, (lower, upper, err) in _GRID_BOUNDS.items():
        value = grid[name]
        if not isinstance(value, int) or value < lower or (upper is not None and value > upper):
            return {"ok": False, "error": err}
        dims[name] = value
    width = dims["width"]
    height = dims["height"]
    cell_size = dims["cell_size"]

    fill_value = raw["fill_value"]
    if not isinstance(fill_value, int):
        return {"ok": False, "error": "bad fill value"}
    observations = raw["observations"]
    if not isinstance(observations, list):
        return {"ok": False, "error": "bad observations"}

    sums = {}
    counts = {}
    degraded = {}
    dropped = 0
    rejected = 0
    saturated = 0
    for obs in observations:
        if not isinstance(obs, dict):
            return {"ok": False, "error": "bad observation"}
        if not all(f in obs and isinstance(obs[f], int) for f in _OBS_FIELDS):
            return {"ok": False, "error": "bad observation"}
        quality = obs["quality"]
        if quality < 0 or quality > 100:
            return {"ok": False, "error": "bad observation"}

        if quality < MIN_QUALITY:
            rejected += 1
            continue

        col = _clamp(obs["x"], cell_size, width)
        if col is None:
            dropped += 1
            continue
        row = _clamp(obs["y"], cell_size, height)
        if row is None:
            dropped += 1
            continue

        key = (row, col)
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated += 1
            continue
        sums[key] = sums.get(key, 0) + obs["value"]
        counts[key] = counts.get(key, 0) + 1
        if quality < GOOD_QUALITY:
            degraded[key] = True

    cells = _averaged_rows(sums, counts, width, height, fill_value)
    flags = _flag_rows(counts, degraded, width, height)
    coverage = len(counts) * 100 // (width * height)
    line = _summary_line(width * height, len(counts), dropped, rejected, saturated, coverage)
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


def _clamp(coord: int, cell_size: int, dim: int) -> int | None:
    """Map a coordinate to a cell index, clamping the trailing edge; None if dropped."""
    if coord < 0:
        return None
    index = coord // cell_size
    if index >= dim:
        if coord - dim * cell_size < cell_size // 2:
            return dim - 1
        return None
    return index


def _averaged_rows(sums: dict, counts: dict, width: int, height: int, fill_value: int) -> list:
    rows = []
    for row in range(height):
        cells = []
        for col in range(width):
            key = (row, col)
            if key in counts:
                cells.append(sums[key] // counts[key])
            else:
                cells.append(fill_value)
        rows.append(cells)
    return rows


def _flag_rows(counts: dict, degraded: dict, width: int, height: int) -> list:
    rows = []
    for row in range(height):
        flags = []
        for col in range(width):
            key = (row, col)
            if key not in counts:
                flags.append("empty")
            elif key in degraded:
                flags.append("degraded")
            else:
                flags.append("good")
        rows.append(flags)
    return rows


def _summary_line(total_cells: int, filled: int, dropped: int, rejected: int, saturated: int, coverage: int) -> str:
    return (
        "cells=" + str(total_cells)
        + ";filled=" + str(filled)
        + ";dropped=" + str(dropped)
        + ";rejected=" + str(rejected)
        + ";saturated=" + str(saturated)
        + ";coverage=" + str(coverage)
    )

